def cantor_numbering(self, N: int) -> str:
        # The first few terms of the Cantor sequence (numerator/denominator)
        cantor_elements = [(1, 1), (2, 1), (3, 2), (4, 1), (5, 3), (6, 2), (7, 4), (8, 3), (9, 5), (10, 2)]

        # Find the N-th element in the Cantor sequence
        i = 0
        while i < len(cantor_elements) and cantor_elements[i][0] <= N:
            i += 1

        if i == 0:
            numerator = 1
            denominator = 1
        elif i == 1:
            numerator = 2
            denominator = 1
        elif i == 2:
            numerator = 3
            denominator = 2
        elif i == 3:
