def max_product(num_str: str, N: int, K: int) -> int:
    def _insert_multipliers(index: int) -> int:
        # Base case: if all K multiplication signs are placed
        if index == K:
            # Calculate the product of all numbers in the current segment
            product = 1
            for i in range(N):
                product *= int(num_str[i])
            return product

        # Recursive case: place a multiplication sign and recurse
        WITH_MULT = _insert_multipliers(index + 1)
        WITHOUT_MULT = 0  # Default value for without multiplication
        if index < N - 1:  # Check if there is a next number to multiply
            WITHOUT_MULT = _insert_multipliers(index + 2)
        return max(WITH_MULT, WITHOUT_MULT)

    # Start the recursion from index 0
    return _insert_multipliers(0)

