    def calculate_checksum(isbn):
        weights = [1, 3, 3, 1, 7, 9, 9, 7, 9, 3, 1]
        checksum = 0
        for weight, digit in zip(weights, isbn[:-1]):
            checksum += weight * (int(digit) if digit.isdigit() else 10)
        return checksum % 10

    # Check the length of the ISBN
    if len(isbn) != 13 or not isbn.startswith("0-"):
        return "Invalid ISBN format"

    # Calculate the expected checksum
    expected_checksum = calculate_checksum(isbn)

    # Check the checksum against the last digit of the ISBN
    if isbn[-1] != expected_checksum % 10:
        # Correct the ISBN by subtracting the expected checksum from the original last digit
        corrected_isbn = isbn[:-1] + str(10 - (expected_checksum % 10))
        return corrected_isbn
    else:
        return "Right"

