        last_digit = int(isbn_str[12])
    else:
        last_digit = ord(isbn_str[12]) - ord('A') + 10

    # Calculate the expected checksum
    expected_checksum = 10 - (sum % 11)

    # Check and correct the ISBN if necessary
    if expected_checksum == last_digit:
        return "Right"
    elif last_digit == 10:
        corrected_isbn = isbn_str[0] + '-' + isbn_str[1] + isbn_str[2] + '-'
        for i in range(6):
