    ans[1] = 1

    for i in range(1, m + 1):
        new_ans = [0] * (n + 1)
        for j in range(1, n + 1):
            new_ans[j] = ans[j - 1] + ans[j]
        ans = new_ans

    return ans[n] % 1000000007

def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    D = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case
    for i in range(1, n + 1):
        D[i][0] = 1

    # Fill the DP table
    for _ in range(m):
        for i in range(1, n + 1):
            D[i][1] = (D[i - 1][0] + D[i - 2][0]) % MOD

    # The result for m times passes
    return D[n][m]

