def decode(encoded: str, original: str, message: str) -> str:
    # Initialize a mapping from original letters to encoded letters
    letter_map = {}

    # Construct the mapping from original to encoded letters
    for i in range(len(original)):
        if original[i] not in letter_map:
            letter_map[original[i]] = encoded[i]
        else:
            if letter_map[original[i]] != encoded[i]:
                # Contradiction found
                return "Failed"

    # Decode the message using the constructed mapping
    decoded_message = ""
    i = 0
    for j in range(len(message)):
        if message[j] in letter_map:
            decoded_message += letter_map[message[j]]
            i += 1
