def catalan_number(n):
    # Base cases
    if n == 0 or n == 1:
        return 1
    # Initialize the list to store the Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1
    # Fill the catalan list using the recursive formula
    for i in range(2, n + 1):
        catalan[i] = 0
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]
    return catalan[n]

def catalan_number(n: int):
    """
    Calculate the nth Catalan number using dynamic programming.

    Args:
        n (int): The position in the Catalan number sequence to compute

    Returns:
        int: The nth Catalan number
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    catalan = [0] * (n + 1)
    catalan[0] = catalan[1] = 1

    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n] % (10**9 + 7)

