def next_permutation(perm: list) -> bool:
    size = len(perm)
    i = size - 2

    while i >= 0 and perm[i] >= perm[i + 1]:
        i -= 1

    if i == -1:
        return False  # Last permutation

    j = size - 1
    while perm[j] <= perm[i]:
        j -= 1

    perm[i], perm[j] = perm[j], perm[i]
    perm[i + 1:] = perm[i + 1:][::-1]
    return True

