    for i in range(n):
        for j in range(i + 1, n):
            if heights[i] <= heights[j]:
                adj[i].append(j)
            if heights[i] >= heights[j]:
                adj[j].append(i)

    # Main function to find the minimum number of students to leave
    def dfs(node, visited, path):
        visited[node] = True
        path.append(node)

        # Explore the neighbors
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, path)

        # Backtrack and add the node if the path is a chain of increasing height
        if len(path) > 1:
            current_height = heights[node]
            while path:
                if current_height > heights[path[-2]]:
