            # Remove the element from the path
            path.remove(max_heightStudent)
            path.append(max_heightStudent + 1)
            path.reverse()
            path.pop()

    min_students_to_leave = len(heights)
    visited = [False] * n
    path = []

    # Iterate through all nodes to find the minimum number of students to leave
    for i in range(n):
