    groups = 0
    for i in range(n):
        if prices[i] > w:  # Skip prices greater than the limit
            continue
        price = prices[i]
        for j in range(i + 1, n):
            if i % 2 == 0:  # Check pairing conditions
                if price < prices[j] and prices[j] <= w - price:
                    price += prices[j]
                    groups += 1
                    break
            else:
                if price < w - prices[j]:
                    price += prices[j]
                    groups += 1
                    break
    return groups

